from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from pydantic import BaseModel
from typing import Optional

app = FastAPI()

@app.post("/test")
async def test_endpoint(name: Optional[str] = Form(None)):
    return {"name": name}

client = TestClient(app)

def test_empty_string_form_value():
    # When name is sent as an empty string, it should be interpreted as None if default is None
    # and it's an optional Form field.
    response = client.post("/test", data={"name": ""})
    print(f"Response: {response.json()}")
    assert response.json() == {"name": None}

if __name__ == "__main__":
    try:
        test_empty_string_form_value()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
